/*
 * A183211  First of two trees generated by floor[(3n-1)/2].
 * https://oeis.org/A183211
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth node obtained by a breadth‑first traversal of
 *            the tree rooted at 1 where the left child of x is
 *            floor((3x-1)/2) and the right child is 3x. Nodes equal to their
 *            parent (this happens only for x = 1 and 2) are omitted. The
 *            implementation keeps a static cache and expands it lazily as...
 * Range:     u8 n <= 47, u16 n <= 1535, u32 n <= 8192, u64 n <= 8192,
 *            u128 n <= 8192, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>   /* for size_t */

/* The following size is comfortably larger than required for n <= 10000
   (the tree expands roughly like 2^level).  It can be increased if
   needed. */
#define CACHE_SIZE 200000

seq_t a(idx_t n)
{
    /* static cached sequence storage */
    static seq_t seq[CACHE_SIZE];
    static size_t seq_len = 0;   /* number of values already generated */

    /* static queue for BFS processing */
    static seq_t queue[CACHE_SIZE];
    static size_t q_front = 0;   /* next element to process */
    static size_t q_back  = 0;   /* one past the last valid element */

    /* initialise on first call */
    if (seq_len == 0) {
        /* first term is 1 */
        seq[0] = (seq_t)1;
        seq_len = 1;

        /* enqueue root node */
        queue[0] = (seq_t)1;
        q_front = 0;
        q_back  = 1;
    }

    /* expand the sequence until we have at least n terms */
    while (seq_len < n) {
        /* pop the next parent node from the queue */
        seq_t parent = queue[q_front++];
        /* avoid overrunning the static arrays (should not happen for n <= 10000) */
        if (q_front >= CACHE_SIZE) break;

        /* compute the two children */
        seq_t left  = ((seq_t)3 * parent - (seq_t)1) / (seq_t)2;
        seq_t right = (seq_t)3 * parent;

        /* enqueue left child if it is not equal to the parent */
        if (left != parent) {
            /* ensure the sequence array has space (guaranteed by CACHE_SIZE) */
            seq[seq_len++] = left;
            queue[q_back++] = left;
            if (q_back >= CACHE_SIZE) break;
        }

        /* enqueue right child (always distinct) */
        seq[seq_len++] = right;
        queue[q_back++] = right;
        if (q_back >= CACHE_SIZE) break;
    }

    /* return the requested term (1‑based index) */
    return seq[n - 1];
}
